            var balances interface{} = this.SafeValue(totalBalance, "balances", []interface{}{})
            var result interface{} = map[string]interface{} {}
            var timestamp interface{} = nil
            var assetIds interface{} = []interface{}{}
            var nonStandardBalances interface{} = []interface{}{}
            for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(balances)); i++ {
                var entry interface{} = ccxt.GetValue(balances, i)
                var entryTimestamp interface{} = this.SafeInteger(entry, "timestamp")
                timestamp = ccxt.Ternary(ccxt.IsTrue((ccxt.IsEqual(timestamp, nil))), entryTimestamp, ccxt.MathMax(timestamp, entryTimestamp))
                var issueTransaction interface{} = this.SafeValue(entry, "issueTransaction")
                var currencyId interface{} = this.SafeString(entry, "assetId")
                var balance interface{} = this.SafeString(entry, "balance")
                var currencyExists interface{} =         (ccxt.InOp(this.Currencies_by_id, currencyId))
                if ccxt.IsTrue(currencyExists) {
                    var code interface{} = this.SafeCurrencyCode(currencyId)
                    ccxt.AddElementToObject(result, code, this.Account())
                    ccxt.AddElementToObject(ccxt.GetValue(result, code), "total", this.FromRealCurrencyAmount(code, balance))
                } else if ccxt.IsTrue(ccxt.IsEqual(issueTransaction, nil)) {
                    ccxt.AppendToArray(&assetIds, currencyId)
                    ccxt.AppendToArray(&nonStandardBalances, balance)
                }
            }
            var nonStandardAssets interface{} =     ccxt.GetArrayLength(assetIds)
            if ccxt.IsTrue(nonStandardAssets) {
                var requestInner interface{} = map[string]interface{} {
                    "ids": assetIds,
                }
        
                response:= (<-this.PublicGetAssets(requestInner))
                ccxt.PanicOnError(response)
                var data interface{} = this.SafeValue(response, "data", []interface{}{})
                for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(data)); i++ {
                    var entry interface{} = ccxt.GetValue(data, i)
                    var balance interface{} = ccxt.GetValue(nonStandardBalances, i)
                    var inner interface{} = this.SafeValue(entry, "data")
                    var precision interface{} = this.ParsePrecision(this.SafeString(inner, "precision"))
                    var ticker interface{} = this.SafeString(inner, "ticker")
                    var code interface{} = this.SafeCurrencyCode(ticker)
                    ccxt.AddElementToObject(result, code, this.Account())
                    ccxt.AddElementToObject(ccxt.GetValue(result, code), "total", ccxt.Precise.StringMul(balance, precision))
                }
            }
            var currentTimestamp interface{} = this.Milliseconds()
            var byteArray interface{} = []interface{}{this.Base58ToBinary(this.ApiKey), this.NumberToBE(currentTimestamp, 8)}
            var binary interface{} = this.BinaryConcatArray(byteArray)
            var hexSecret interface{} = this.BinaryToBase16(this.Base58ToBinary(this.Secret))
            var signature interface{} = this.Axolotl(this.BinaryToBase16(binary), hexSecret, ccxt.Ed25519)
            var matcherRequest interface{} = map[string]interface{} {
                "publicKey": this.ApiKey,
                "signature": signature,
                "timestamp": ccxt.ToString(currentTimestamp),
            }
        
            reservedBalance:= (<-this.MatcherGetMatcherBalanceReservedPublicKey(matcherRequest))
            ccxt.PanicOnError(reservedBalance)
            // { WAVES: 200300000 }
            var reservedKeys interface{} = ccxt.ObjectKeys(reservedBalance)
            for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(reservedKeys)); i++ {
                var currencyId interface{} = ccxt.GetValue(reservedKeys, i)
                var code interface{} = this.SafeCurrencyCode(currencyId)
                if !ccxt.IsTrue((ccxt.InOp(result, code))) {
                    ccxt.AddElementToObject(result, code, this.Account())
                }
                var amount interface{} = this.SafeString(reservedBalance, currencyId)
                ccxt.AddElementToObject(ccxt.GetValue(result, code), "used", this.FromRealCurrencyAmount(code, amount))
            }
            var wavesRequest interface{} = map[string]interface{} {
                "address": wavesAddress,
            }
        
            wavesTotal:= (<-this.NodeGetAddressesBalanceAddress(wavesRequest))
            ccxt.PanicOnError(wavesTotal)
